import {createSlugger, type Slugger, type SluggerOptions} from './slugger';

/**
 * The supported syntaxes for custom Markdown heading IDs.
 *
 * - `'classic'` uses the `{#id}` format.
 * - `'mdx-comment'` uses the `{/* #id *␣/}` format (a valid MDX comment).
 */
export type HeadingIdSyntax = 'classic' | 'mdx-comment';

// Classic syntax: `{#some-heading}` at the end of the heading.
// The ID can contain any characters except `{#` and `}`.
const classicHeadingIdRegex = /\s*\{#(?<id>(?:.(?!\{#|\}))*.)\}$/;

// MDX comment syntax: `{/* #some-heading *␣/}` at the end of the heading.
// Whitespace around the id inside the comment is trimmed, and the id itself
// can't contain whitespace or braces.
const mdxCommentHeadingIdRegex =
  /\s*\{\/\*\s*#(?<id>[^\s{}]+)\s*\*\/\}$/;

function getHeadingIdRegex(syntax: HeadingIdSyntax): RegExp {
  return syntax === 'mdx-comment'
    ? mdxCommentHeadingIdRegex
    : classicHeadingIdRegex;
}

/**
 * Parses custom ID from a heading. The ID can contain any characters except
 * `{#` and `}` (classic syntax).
 *
 * @param heading e.g. `## Some heading {#some-heading}` where the last
 * character must be `}` for the ID to be recognized
 * @param syntax the heading ID syntax to recognize. `'classic'` recognizes
 * `{#id}`, `'mdx-comment'` recognizes `{/* #id *␣/}`. Each syntax only
 * recognizes its own format.
 */
export function parseMarkdownHeadingId(
  heading: string,
  syntax: HeadingIdSyntax = 'classic',
): {
  /**
   * The heading content sans the ID part, right-trimmed. e.g. `## Some heading`
   */
  text: string;
  /** The heading ID. e.g. `some-heading` */
  id: string | undefined;
} {
  const customHeadingIdRegex = getHeadingIdRegex(syntax);
  const matches = customHeadingIdRegex.exec(heading);
  if (matches) {
    return {
      text: heading.replace(matches[0]!, ''),
      id: matches.groups!.id!,
    };
  }
  return {text: heading, id: undefined};
}

/**
 * Parses an existing heading ID regardless of the syntax it uses. Returns the
 * heading text, the parsed id, and which syntax the id was written in.
 */
function parseExistingHeadingId(heading: string): {
  text: string;
  id: string | undefined;
  syntax: HeadingIdSyntax | undefined;
} {
  const classic = parseMarkdownHeadingId(heading, 'classic');
  if (classic.id) {
    return {...classic, syntax: 'classic'};
  }
  const mdxComment = parseMarkdownHeadingId(heading, 'mdx-comment');
  if (mdxComment.id) {
    return {...mdxComment, syntax: 'mdx-comment'};
  }
  return {text: heading, id: undefined, syntax: undefined};
}

/**
 * MDX 2 requires escaping { with a \ so our anchor syntax need that now.
 * See https://mdxjs.com/docs/troubleshooting-mdx/#could-not-parse-expression-with-acorn-error
 */
export function escapeMarkdownHeadingIds(content: string): string {
  const markdownHeadingRegexp = /(?:^|\n)#{1,6}(?!#).*/g;
  return content.replaceAll(markdownHeadingRegexp, (substring) =>
    // TODO probably not the most efficient impl...
    substring
      .replace('{#', '\\{#')
      // prevent duplicate escaping
      .replace('\\\\{#', '\\{#'),
  );
}

function unwrapMarkdownLinks(line: string): string {
  return line.replace(
    /\[(?<alt>[^\]]+)\]\([^)]+\)/g,
    (match, p1: string) => p1,
  );
}

/** Formats a heading ID slug according to the requested syntax. */
function formatHeadingId(id: string, syntax: HeadingIdSyntax): string {
  return syntax === 'mdx-comment' ? `{/* #${id} */}` : `{#${id}}`;
}

/**
 * Generates a new heading ID from the heading text and appends it using the
 * requested syntax.
 */
function addHeadingId({
  line,
  slugger,
  maintainCase,
  syntax,
}: {
  line: string;
  slugger: Slugger;
  maintainCase: boolean;
  syntax: HeadingIdSyntax;
}): string {
  let headingLevel = 0;
  while (line.charAt(headingLevel) === '#') {
    headingLevel += 1;
  }

  const headingText = line.slice(headingLevel).trimEnd();
  const headingHashes = line.slice(0, headingLevel);
  const slug = slugger.slug(unwrapMarkdownLinks(headingText).trim(), {
    maintainCase,
  });

  return `${headingHashes}${headingText} ${formatHeadingId(slug, syntax)}`;
}

export type WriteHeadingIDOptions = SluggerOptions & {
  /** The syntax used to write the generated heading IDs. */
  syntax?: HeadingIdSyntax;
  /**
   * Rewrite existing heading IDs (in any syntax) using the target syntax,
   * preserving the ID value. IDs already in the target syntax are kept as-is.
   */
  migrate?: boolean;
  /** Overwrite existing heading IDs, generating new ones from the text. */
  overwrite?: boolean;
};

/**
 * Takes Markdown content, returns new content with heading IDs written.
 * Respects existing IDs (unless `overwrite=true`) and never generates colliding
 * IDs (through the slugger).
 */
export function writeMarkdownHeadingId(
  content: string,
  options?: WriteHeadingIDOptions,
): string {
  const {
    maintainCase = false,
    overwrite = false,
    migrate = false,
    syntax = 'classic',
  } = options ?? {};

  if (overwrite && migrate) {
    throw new Error(
      'Heading ids can either be overwritten or migrated, not both at the same time',
    );
  }

  const lines = content.split('\n');
  const slugger = createSlugger();

  // If we can't overwrite existing slugs, make sure other headings don't
  // generate colliding slugs by first marking these slugs as occupied
  if (!overwrite) {
    lines.forEach((line) => {
      const parsedHeading = parseExistingHeadingId(line);
      if (parsedHeading.id) {
        slugger.slug(parsedHeading.id);
      }
    });
  }

  let inCode = false;
  return lines
    .map((line) => {
      if (line.startsWith('```')) {
        inCode = !inCode;
        return line;
      }
      // Ignore h1 headings, as we don't create anchor links for those
      if (inCode || !line.startsWith('##')) {
        return line;
      }
      const parsedHeading = parseExistingHeadingId(line);

      if (parsedHeading.id) {
        if (overwrite) {
          // Discard the existing ID and generate a new one from the text
          return addHeadingId({
            line: parsedHeading.text,
            slugger,
            maintainCase,
            syntax,
          });
        }
        if (migrate) {
          // Keep the existing ID, but rewrite it using the target syntax
          if (parsedHeading.syntax === syntax) {
            return line;
          }
          return `${parsedHeading.text} ${formatHeadingId(
            parsedHeading.id,
            syntax,
          )}`;
        }
        // Do not process if id is already there
        return line;
      }
      return addHeadingId({
        line: parsedHeading.text,
        slugger,
        maintainCase,
        syntax,
      });
    })
    .join('\n');
}
